script:
$env:Path += ";C:\Users\E\AppData\Local\hermes\bin"
$job = Start-Job -ScriptBlock {
  $env:Path += ";C:\Users\E\AppData\Local\hermes\bin"
  hermes -z "Reply with exactly: HERMES_OK" --provider zen -m "space-bunny-free" 2>&1 | Select-Object -First 10
}
if (Wait-Job $job -Timeout 90) {
  "Result:"
  Receive-Job $job
} else {
  "TIMED OUT after 90s"
  Stop-Job $job
}
Remove-Job $job -Force
